  cameraAccessDesc: "ஊழியர் சுயவிவரங்கள் மற்றும் ஆவண ஸ்கேனிங்கிற்கான புகைப்படங்களை எடுக்கவும். முக்கியமான தகவல்களை விரைவாக படமெடுக்கவும் சேமிக்கவும் இது உதவுகிறது.",
  whyLocationNeeded: "நாணய அமைப்புகளுக்கு உங்கள் நாட்டைத் தானாகக் கண்டறிய பயன்படுத்தப்படுகிறது",
  whyStorageNeeded: "காப்பு கோப்புகள் மற்றும் ஏற்றுமதி செய்யப்பட்ட அறிக்கைகளுக்குத் தேவை",
  whyMediaNeeded: "ஊழியர் புகைப்படங்கள் மற்றும் ஆவண இணைப்புகளுக்குப் பயன்படுத்தப்படுகிறது",
  whyNotificationsNeeded: "கட்டண நினைவூட்டல்கள் மற்றும் எச்சரிக்கைகளுக்குப் பயன்படுத்தப்படுகிறது",
